shell_commands:
cat >> src/orchestration/orchestratorHelpers.test.ts <<'EOF'

describe('addUsage', () => {
  it('sums each token field, skipping a round that reported no usage', () => {
    let total = addUsage(undefined, {inputTokens: 2, outputTokens: 1, totalTokens: 3});
    total = addUsage(total, undefined);
    total = addUsage(total, {inputTokens: 7, outputTokens: 4, totalTokens: 11});

    expect(total).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
    expect(addUsage(undefined, undefined)).toBeUndefined();
  });
});
EOF
sed -i '1s/.*/import {addUsage, shouldContinueToolLoop} from '"'"'.\/orchestratorHelpers.js'"'"';/' src/orchestration/orchestratorHelpers.test.ts
head -1 src/orchestration/orchestratorHelpers.test.ts
timeout 300 npx jest src/orchestration/orchestratorHelpers.test.ts 2>&1 | tail -15

cat >> src/orchestration/orchestratorHelpers.ts <<'EOF'

export function addUsage(total: UsageMetadata | undefined, round: UsageMetadata | undefined): UsageMetadata | undefined {
  if (!round) return total;
  if (!total) return round;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}
EOF
timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js src/orchestration/orchestratorHelpers.test.ts 2>&1 | grep -E "Tests:|✕"
